```go
package main

import (
    "fmt"
    "io"
)

type MemoryLog []byte

func (m *MemoryLog) Write(p []byte) (int, error) {
    *m = append(*m, p...)
    return len(p), nil
}

var _ io.Writer = (*MemoryLog)(nil)

func main() {
    var log MemoryLog
    _, _ = fmt.Fprint(&log, "ready")
    fmt.Println(string(log))
}
```
`*MemoryLog` satisfies `io.Writer` through its `Write` method. Neither declaration names the other as an implementation.

```go
package main

import "fmt"

type Labeler interface{ Label() string }

type Item struct{ Name string }

func (i *Item) Label() string {
    if i == nil {
        return "<missing>"
    }
    return i.Name
}

func main() {
    var item *Item
    var labeler Labeler = item
    fmt.Println(item == nil, labeler == nil, labeler.Label())
}
```
The output is `true false <missing>`. The interface has dynamic type `*Item`, and the method deliberately handles the nil pointer.

```go
package main

import "fmt"

func render(value any) string {
    switch value := value.(type) {
    case string:
        return "text=" + value
    case int:
        return fmt.Sprintf("number=%d", value)
    case fmt.Stringer:
        return "stringer=" + value.String()
    default:
        return fmt.Sprintf("unsupported=%T", value)
    }
}

func main() {
    fmt.Println(render("go"))
    fmt.Println(render(7))
}
```
Each case uses a value narrowed to that case's static type. Unsupported inputs reach the explicit default rather than panicking.
